
.codex {
  max-width: 820px;
  margin: 6px auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 14px;
  padding: 10px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
}

.danger-pulse {
  border-color: rgba(192, 69, 59, 0.6);
  animation: pulse 2.4s ease-in-out infinite;
}

@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
  }
  50% {
    box-shadow: 0 6px 30px rgba(192, 69, 59, 0.35);
  }
}

.topbar {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.who {
  flex: 1;
  min-width: 200px;
}

.name {
  font-size: 18px;
  font-weight: 800;
  color: var(--c-primary);
}

.title {
  font-size: 13px;
  color: var(--c-muted);
  font-weight: 500;
}

.sub {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  margin-top: 5px;
}

.realm {
  width: 150px;
}

.lv {
  font-size: 20px;
  font-weight: 800;
}

.stage {
  font-size: 12px;
  color: var(--c-primary);
  margin-bottom: 5px;
}

.tiny {
  font-size: 11px;
  color: var(--c-muted);
  margin-top: 3px;
}

.clock {
  text-align: right;
  font-size: 12px;
  color: var(--c-muted);
}

.clock .line {
  margin-bottom: 2px;
}

.countdown {
  display: inline-block;
  margin-top: 3px;
  padding: 2px 8px;
  border-radius: 10px;
  border: 1px solid var(--c-border);
  color: var(--c-primary);
}

.countdown.warn {
  color: #fff;
  background: var(--c-danger);
  border-color: var(--c-danger);
  animation: blink 1.2s steps(2, start) infinite;
}

.countdown.jumped {
  color: var(--c-muted);
  border-style: dashed;
}

@keyframes blink {
  50% {
    opacity: 0.55;
  }
}

.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 8px;
  flex-wrap: wrap;
}

.tabs button {
  border: 1px solid var(--c-border);
  background: var(--c-panel);
  color: var(--c-text);
  border-radius: 8px;
  padding: 6px 12px;
  cursor: pointer;
  font-weight: 600;
}

.tabs button.on {
  background: var(--c-primary);
  border-color: var(--c-primary);
  color: #1b1712;
}

.tabs .ico {
  margin-right: 4px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 8px;
}

.pane {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.card {
  margin-bottom: 0;
}

.card h3 {
  margin: 0 0 8px;
  font-size: 14px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 5px;
  letter-spacing: 0.06em;
}

.card.dark {
  border-color: rgba(192, 69, 59, 0.45);
}

.res {
  margin-bottom: 7px;
}

.res label,
.prof label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--c-muted);
  margin-bottom: 3px;
}

.res b,
.prof b {
  color: var(--c-text);
}

.kv {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 13px;
  padding: 3px 0;
}

.kv span {
  color: var(--c-muted);
}

.kv.small {
  font-size: 12px;
}

.danger {
  color: var(--c-danger) !important;
}

.skill-name {
  font-size: 16px;
  font-weight: 800;
  color: var(--c-accent);
  margin-bottom: 6px;
}

.note {
  font-size: 12px;
  color: var(--c-muted);
  margin-top: 5px;
  line-height: 1.6;
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.skill-list {
  margin-top: 8px;
}

.skill-list h4 {
  margin: 0 0 3px;
  font-size: 12px;
  color: var(--c-muted);
}

.equip-row {
  margin-bottom: 8px;
}

.equip-row label {
  display: block;
  font-size: 12px;
  color: var(--c-muted);
  margin-bottom: 3px;
}

.char-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 8px;
}

.char-card {
  border: 1px solid var(--c-border);
  border-radius: 9px;
  padding: 9px;
  background: var(--c-panel-2);
}

.char-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.faction {
  margin-bottom: 8px;
}

.task {
  border-top: 1px dashed var(--c-border);
  padding-top: 6px;
  margin-top: 6px;
}

.task-head {
  display: flex;
  gap: 5px;
  align-items: center;
  flex-wrap: wrap;
}

.map-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.zone {
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 10px 8px;
  text-align: center;
  background: var(--c-panel-2);
}

.zone b {
  display: block;
  font-size: 13px;
}

.zone small {
  color: var(--c-muted);
  font-size: 11px;
}

.zone.here {
  border-color: var(--c-primary);
  box-shadow: inset 0 0 0 1px var(--c-primary);
  background: var(--c-primary-soft);
}

.loading {
  padding: 14px;
  text-align: center;
  color: var(--c-muted);
}
